from pathlib import Path
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_CENTER
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle

def generate_result_pdf(result, path):
    Path(path).parent.mkdir(parents=True,exist_ok=True)
    doc=SimpleDocTemplate(str(path),pagesize=A4,rightMargin=40,leftMargin=40,topMargin=40,bottomMargin=40)
    styles=getSampleStyleSheet(); title=ParagraphStyle("title",parent=styles["Title"],alignment=TA_CENTER,spaceAfter=16)
    story=[Paragraph("ExamForge",title),Paragraph("Official Result Card",styles["Heading2"]),Spacer(1,12)]
    status="PASS" if result["passed"] else "FAIL"
    data=[["Student",result["candidate_name"]],["Email / Student ID",result["candidate_email"]],["Exam",result["exam_title"]],["Exam Date",result["created_at"]], ["Result ID",result["id"]],["Score",f"{result['score']:.2f} / {result['max_marks']:.2f}"],["Percentage",f"{result['percentage']:.2f}%"],["Status",status],["Correct / Wrong / Skipped",f"{result['correct_count']} / {result['wrong_count']} / {result['skipped_count']}"],["Time Taken",f"{result['time_taken_seconds']//60}m {result['time_taken_seconds']%60}s"],["Security Events",str(result['security_event_count'])]]
    table=Table(data,colWidths=[150,330]); table.setStyle(TableStyle([("BACKGROUND",(0,0),(0,-1),colors.HexColor("#eef2f7")),("GRID",(0,0),(-1,-1),0.5,colors.HexColor("#ccd3dd")),("FONTNAME",(0,0),(0,-1),"Helvetica-Bold"),("VALIGN",(0,0),(-1,-1),"TOP"),("PADDING",(0,0),(-1,-1),8)])); story += [table,Spacer(1,20),Paragraph("Generated by ExamForge. This result is computed server-side from the recorded attempt.",styles["BodyText"])]
    doc.build(story)
